   151  int
   152  PackLinuxElf32::checkEhdr(Elf32_Ehdr const *ehdr) const
   153  {
   154      const unsigned char * const buf = ehdr->e_ident;
   155
   156      if (0!=memcmp(buf, "\x7f\x45\x4c\x46", 4)  // "\177ELF"
   157      ||  buf[Elf32_Ehdr::EI_CLASS]!=ei_class
   158      ||  buf[Elf32_Ehdr::EI_DATA] !=ei_data
   159      ) {
   160          return -1;
   161      }
   162      if (!memcmp(buf+8, "FreeBSD", 7))                   // branded
   163          return 1;
   164
   165      int const type = get_te16(&ehdr->e_type);
   166      if (type != Elf32_Ehdr::ET_EXEC && type != Elf32_Ehdr::ET_DYN)
   167          return 2;
   168      if (get_te16(&ehdr->e_machine) != (unsigned) e_machine)
   169          return 3;
   170      if (get_te32(&ehdr->e_version) != Elf32_Ehdr::EV_CURRENT)
   171          return 4;
   172      if (e_phnum < 1)
   173          return 5;
   174      if (get_te16(&ehdr->e_phentsize) != sizeof(Elf32_Phdr))
   175          return 6;
   176
   177      if (type == Elf32_Ehdr::ET_EXEC) {
   178          // check for Linux kernels
   179          unsigned const entry = get_te32(&ehdr->e_entry);
   180          if (entry == 0xC0100000)    // uncompressed vmlinux
   181              return 1000;
   182          if (entry == 0x00001000)    // compressed vmlinux
   183              return 1001;
   184          if (entry == 0x00100000)    // compressed bvmlinux
   185              return 1002;
   186      }
   187
   188      // FIXME: add more checks for kernels
   189
   190      // FIXME: add special checks for other ELF i386 formats, like
   191      //        NetBSD, OpenBSD, Solaris, ....
   192
   193      // success
   194      return 0;
   195  }
